from __future__ import annotations

import pytest

from llm_router._internal.capabilities.content import (
    TextPart,
    normalize_content,
)

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("REQ_MULTIMODAL_CONTENT_NORMALIZATION[revision==2]")
@pytest.mark.parametrize("role", ["user", "assistant"])
def test_plain_string_content_keeps_role_and_single_text_part(role: str) -> None:
    value = "Summarize the quarterly report in two sentences."

    normalized = normalize_content(value, role=role)

    assert normalized.role == role
    assert normalized.parts == (TextPart(kind="text", text=value),)
    assert len(normalized.parts) == 1
    assert normalized.meta == {}
